# Request parser


def _header_block_slow(cap, block_start, header_start):
    headers = []
    cursor = header_start
    while True:
        content, next_cursor = _line(cap, cursor)
        if next_cursor - block_start > 65536:
            raise _ParseFailure("syntax")
        if content == b"":
            return headers, next_cursor
        if len(headers) + 1 > 128:
            raise _ParseFailure("syntax")
        headers.append(_field(content))
        cursor = next_cursor


def _header_block_fast(cap, block_start, header_start):
    """Parse a complete header section from progressively larger windows.

    Short/repeated header blocks are by far the common case in a capture
    audit.  Reading a bounded window and splitting lines with bytes.find()
    avoids revisiting the compressed rope once per field.
    """
    remaining = cap.total - header_start
    if remaining <= 0:
        return _header_block_slow(cap, block_start, header_start)
    window = min(remaining, 256)
    cap_window = min(remaining, 65536)
    while True:
        data = cap.read(header_start, header_start + window, window)
        pos = 0
        headers = []
        while True:
            lf = data.find(b"\\n", pos)
            if lf < 0:
                available = len(data) - pos
                if window < remaining and available > 8193:
                    raise _ParseFailure("syntax")
                break
            if lf == pos or data[lf - 1] != 0x0D:
                raise _ParseFailure("syntax")
            content_length = lf - 1 - pos
            if content_length > 8192:
                raise _ParseFailure("syntax")
            next_global = header_start + lf + 1
            if next_global - block_start > 65536:
                raise _ParseFailure("syntax")
            content = data[pos:lf - 1]
            if content == b"":
                return headers, next_global
            if len(headers) + 1 > 128:
                raise _ParseFailure("syntax")
            headers.append(_field(content))
            pos = lf + 1
        if window == remaining:
            available = len(data) - pos
            if available <= 8193:
                raise _ParseFailure("incomplete")
            raise _ParseFailure("syntax")
        if window >= cap_window:
            break
        window = min(cap_window, window * 2)
    return _header_block_slow(cap, block_start, header_start)


def _parse_request(cap: Capture, start: int, state: _AuditState):
    content, cursor = _line(cap, start)
    method, target = _request_line(content)
    block_start = start
    if cursor - block_start > 65536:
        raise _ParseFailure("syntax")

    headers, cursor = _header_block_fast(cap, block_start, cursor)
'''
